import math

def is_power_of_two(num):
    if num <= 0:
        return False
    return (num & (num - 1)) == 0

solutions = []
N_max = 5
X_max = 15

for n in range(2, N_max + 1):
    # x must be > n and <= 15
    for x in range(n + 1, X_max + 1):
        lhs = x**n + x
        target = lhs - 2

        if is_power_of_two(target):
            # Find k such that 2^k = target
            # k = log2(target)
            k = int(math.log2(target))

            # Sanity check: 2^k should equal target
            if (2**k) == target:
                solutions.append((x, n, k))

print("Found solutions (x, n, k):")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No solutions found in the specified range.")

